from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # (employee, year) -> list of (start, end) approved requests
        self._requests: dict[tuple[str, int], list[tuple[date, date]]] = {}

    def _is_working_day(self, d: date) -> bool:
        return d.weekday() < 5 and d not in self.holidays

    def _count_leave_days(self, start: date, end: date) -> int:
        count = 0
        cur = start
        while cur <= end:
            if self._is_working_day(cur):
                count += 1
            cur += timedelta(days=1)
        return count

    def remaining(self, employee: str, year: int) -> int:
        used = 0
        for start, end in self._requests.get((employee, year), []):
            used += self._count_leave_days(start, end)
        return self.days_per_year - used

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Request must be made at least 3 days before start date.")

        # Generate the leave days for the request
        days = []
        cur = start
        while cur <= end:
            if self._is_working_day(cur):
                days.append(cur)
            cur += timedelta(days=1)

        # A request spanning multiple years consumes days in each year.
        # Check availability per year.
        per_year: dict[int, int] = {}
        for d in days:
            per_year[d.year] = per_year.get(d.year, 0) + 1

        for year, needed in per_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Not enough leave days remaining in {year} "
                    f"(needed {needed}, have {self.remaining(employee, year)})."
                )

        # All good; record the request under the start year as well as
        # per-year buckets for accounting.
        for d in days:
            key = (employee, d.year)
            self._requests.setdefault(key, [])

        # Record the request for each year it touches by adding a per-year
        # entry representing exactly the days in that year.
        for year, needed in per_year.items():
            year_days = [d for d in days if d.year == year]
            self._requests[(employee, year)].append((year_days[0], year_days[-1]))

        return len(days)
